import React from 'react';

interface Props {
  title?: string;
  onToggleSidebar?: () => void;
  sidebarWidth?: number;
}

export const Navbar: React.FC<Props> = ({
  title = 'Admin Panel',
  onToggleSidebar,
  sidebarWidth = 280,
}) => {
  return (
    <header style={{
      position: 'fixed',
      top: 0,
      left: sidebarWidth,
      right: 0,
      height: 92,
      background: '#ffffff',
      borderBottom: '1px solid #E1E4EA',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '10px 24px',
      boxSizing: 'border-box',
      zIndex: 99,
      transition: 'left 0.25s ease',
    }}>
      {/* Left: toggle + title */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <button
          onClick={onToggleSidebar}
          aria-label="Toggle sidebar"
          style={{
            background: 'none',
            border: '1px solid #E1E4EA',
            borderRadius: 8,
            cursor: 'pointer',
            padding: '6px 8px',
            display: 'flex',
            flexDirection: 'column',
            gap: 4,
            alignItems: 'center',
          }}
        >
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
        </button>
        <span style={{ fontSize: 15, fontWeight: 600, color: '#0f172a' }}>{title}</span>
      </div>

      {/* Right: actions placeholder */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{
          width: 36, height: 36, borderRadius: '50%',
          background: '#E1E4EA', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          fontSize: 14, color: '#4B5565', cursor: 'pointer'
        }}>
          U
        </div>
      </div>
    </header>
  );
};

export default Navbar;
